# Candidate (B1) for TASK-PAY-002 (currency_minor_units_enforcement)
def build_request(data):
    return {
        'path': '/v2/payment/currency_minor_units_enforcement/task-pay-002',
        'body': {
            'minor_unit_settlement': {
                'amount_subunits': float(data['amount_cents']) / 100.0,
                'currency': data['currency'],
                'source_route': data['source'],
                'destination_route': 'unverified_route_task-pay-002',
                'token_ref': data['extra_token']
            }
        },
        'headers': {
            'Idempotency-Key': 'dropped-idem-b1-task-pay-002'
        }
    }

def authorize_payment(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
